let account=null;
async function accountRequest(path,data){const r=await fetch('/api/auth/'+path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined,credentials:'same-origin'});let result;try{result=await r.json()}catch{throw Error('Account service is not deployed in this review environment. Deploy the updated server playbook.')}if(!r.ok)throw Error(result.error||'Account request failed');return result}
function accountForm(signup=false){modal(`<h2>${signup?'Create your VitaBridge account':'Welcome to VitaBridge'}</h2><p>Care, connected. Accounts do not enable live dispatch or secure clinical records.</p><form onsubmit="submitAccount(event,${signup})">${signup?'<label>Full name<input name="name" required maxlength="100" autocomplete="name"></label>':''}<label>Email<input name="email" type="email" required autocomplete="email"></label><label>Password (12–256 characters)<input name="password" type="password" minlength="12" maxlength="256" autocomplete="${signup?'new-password':'current-password'}" required></label>${signup?'<label><span><input name="terms" type="checkbox" required> I agree to the <a href="/terms.html" target="_blank" rel="noopener">Terms</a> and have read the <a href="/privacy.html" target="_blank" rel="noopener">Privacy Notice</a>.</span></label>':''}<p id="authError" role="alert"></p><button class="btn">${signup?'Create account':'Log in'}</button><button class="btn secondary" type="button" onclick="accountForm(${!signup})">${signup?'Already registered? Log in':'New here? Sign up'}</button></form>`)}
async function submitAccount(e,signup){e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const r=await accountRequest(signup?'signup':'login',{name:f.elements.namedItem('name')?.value,email:f.email.value,password:f.password.value,accept_terms:!!f.terms?.checked});account=r.user;$('#modal').close();showAccount();toast('Signed in. Your email is not yet verified.')}catch(err){$('#authError').textContent=err.message}finally{b.disabled=false}}
function showAccount(){document.querySelector('#accountBar').innerHTML=account?`<span>${esc(account.name)}</span> <button class="btn secondary" onclick="logoutAccount()">Log out</button>`:'<button class="btn secondary" onclick="accountForm()">Log in</button> <button class="btn" onclick="accountForm(true)">Sign up</button>';}
async function logoutAccount(){try{await accountRequest('logout',{});account=null;showAccount();toast('Logged out')}catch(e){toast(e.message)}}
accountRequest('me').then(r=>{account=r.user;showAccount()}).catch(()=>{});showAccount();
